//! Translated from linuxdoom-1.10/tables.c and linuxdoom-1.10/tables.h
//!
//! Trigonometric lookup tables for the fixed-point engine.
//! Do not try to look them up :-).
//!
//! - `FINETANGENT[4096]` — Tangent LUT. Works with BAM (12 of 16 bit, by shifting).
//! - `FINESINE[10240]` — Sine lookup. Also serves as cosine (PI/2 phase shift).
//! - `TANTOANGLE[2049]` — ArcTan LUT, maps tan(angle) to angle fast.
//!
//! All table entries are copied verbatim from the original C source to ensure
//! bit-identical deterministic behavior. Even a single wrong value would break
//! rendering and physics calculations throughout the engine.

use super::angle::{Angle, ANG180, ANG270, ANG90};
use super::fixed::Fixed;

// ---------------------------------------------------------------------------
// Constants (from tables.h lines 50-76)
// ---------------------------------------------------------------------------

/// Number of fine-angle subdivisions for a full circle.
/// Original C: `#define FINEANGLES 8192`
pub const FINEANGLES: usize = 8192;

/// Bitmask for fine-angle indices: `FINEANGLES - 1` = 8191.
/// Original C: `#define FINEMASK (FINEANGLES-1)`
pub const FINEMASK: usize = FINEANGLES - 1;

/// Right-shift amount to convert a BAM angle to a fine-angle index.
/// Maps the 32-bit BAM range `0..0xFFFFFFFF` onto the 13-bit range `0..8191`.
/// Original C: `#define ANGLETOFINESHIFT 19`
pub const ANGLETOFINESHIFT: u32 = 19;

/// Range for slope (tangent) values used in `TANTOANGLE` lookups.
/// Original C: `#define SLOPERANGE 2048`
pub const SLOPERANGE: usize = 2048;

/// Number of bits used for slope representation.
/// Original C: `#define SLOPEBITS 11`
pub const SLOPEBITS: usize = 11;

/// Remaining bits after slope: `FRACBITS - SLOPEBITS = 16 - 11 = 5`.
/// Original C: `#define DBITS (FRACBITS-SLOPEBITS)`
pub const DBITS: usize = 16 - SLOPEBITS;

// ---------------------------------------------------------------------------
// SlopeDiv utility function (from tables.c lines 49-62)
// ---------------------------------------------------------------------------

/// Utility function for `point_to_angle`.
///
/// Computes a slope index from a numerator and denominator, clamped to
/// `SLOPERANGE`. Used to index into the `TANTOANGLE` lookup table.
///
/// # Arguments
/// * `num` — Numerator (typically the shorter axis distance)
/// * `den` — Denominator (typically the longer axis distance)
///
/// # Returns
/// A value in `0..=SLOPERANGE` suitable for indexing `TANTOANGLE`.
///
/// Original C (tables.c lines 49-62):
/// ```c
/// int SlopeDiv(unsigned num, unsigned den) {
///     unsigned ans;
///     if (den < 512) return SLOPERANGE;
///     ans = (num<<3) / (den>>8);
///     return ans <= SLOPERANGE ? ans : SLOPERANGE;
/// }
/// ```
pub fn slope_div(num: u32, den: u32) -> u32 {
    if den < 512 {
        return SLOPERANGE as u32;
    }
    let ans = (num << 3) / (den >> 8);
    if ans <= SLOPERANGE as u32 {
        ans
    } else {
        SLOPERANGE as u32
    }
}

// ---------------------------------------------------------------------------
// Finecosine helper (replaces the C pointer: finecosine = &finesine[FINEANGLES/4])
// ---------------------------------------------------------------------------

/// Access the fine cosine value at the given index.
///
/// In the original C, cosine is accessed via a pointer into the sine table:
/// ```c
/// fixed_t* finecosine = &finesine[FINEANGLES/4];
/// ```
/// This Rust equivalent indexes `FINESINE` with a PI/2 (2048-entry) phase shift.
///
/// # Arguments
/// * `index` — Fine-angle index (typically `0..FINEANGLES`)
///
/// # Panics
/// Panics if `index + FINEANGLES/4` is out of bounds for `FINESINE`.
#[inline]
pub fn finecosine(index: usize) -> Fixed {
    FINESINE[index + FINEANGLES / 4]
}

// ---------------------------------------------------------------------------
// point_to_angle — R_PointToAngle equivalent (from r_main.c lines 278-376)
// ---------------------------------------------------------------------------

/// Compute the angle from the origin to the point `(x, y)`.
///
/// To get a global angle from Cartesian coordinates, the coordinates are
/// flipped until they are in the first octant, then the shorter axis is
/// scaled and divided by the longer axis to get a tangent (slope) value
/// which is looked up in the `TANTOANGLE` table.
///
/// In the original C this function subtracts `viewx`/`viewy` from the inputs.
/// In the Rust port, callers must pass pre-subtracted relative coordinates
/// (i.e., `x - viewx`, `y - viewy`) to keep this function free of global state.
///
/// # Arguments
/// * `x` — Relative X coordinate (target_x - origin_x)
/// * `y` — Relative Y coordinate (target_y - origin_y)
///
/// # Returns
/// The BAM angle from the origin toward `(x, y)`.
///
/// Original C: `R_PointToAngle` in `r_main.c` lines 292-376.
pub fn point_to_angle(x: Fixed, y: Fixed) -> Angle {
    let x = x.0;
    let y = y.0;

    if x == 0 && y == 0 {
        return Angle(0);
    }

    if x >= 0 {
        if y >= 0 {
            // First quadrant
            if x > y {
                // Octant 0
                TANTOANGLE[slope_div(y as u32, x as u32) as usize]
            } else {
                // Octant 1
                ANG90 - Angle(1) - TANTOANGLE[slope_div(x as u32, y as u32) as usize]
            }
        } else {
            // Fourth quadrant (y < 0)
            // Use wrapping_neg for C-equivalent behavior on i32::MIN
            let y = y.wrapping_neg();
            if x > y {
                // Octant 7 (wrapping: -angle = 0 - angle)
                Angle(0u32.wrapping_sub(TANTOANGLE[slope_div(y as u32, x as u32) as usize].0))
            } else {
                // Octant 6
                ANG270 + TANTOANGLE[slope_div(x as u32, y as u32) as usize]
            }
        }
    } else {
        // x < 0
        // Use wrapping_neg for C-equivalent behavior on i32::MIN
        let x = x.wrapping_neg();
        if y >= 0 {
            // Second quadrant
            if x > y {
                // Octant 3
                ANG180 - Angle(1) - TANTOANGLE[slope_div(y as u32, x as u32) as usize]
            } else {
                // Octant 2
                ANG90 + TANTOANGLE[slope_div(x as u32, y as u32) as usize]
            }
        } else {
            // Third quadrant (y < 0)
            // Use wrapping_neg for C-equivalent behavior on i32::MIN
            let y = y.wrapping_neg();
            if x > y {
                // Octant 4
                ANG180 + TANTOANGLE[slope_div(y as u32, x as u32) as usize]
            } else {
                // Octant 5
                ANG270 - Angle(1) - TANTOANGLE[slope_div(x as u32, y as u32) as usize]
            }
        }
    }
}

/// Compute the angle from point `(x1, y1)` to point `(x2, y2)`.
///
/// Convenience wrapper that subtracts the source point before calling
/// [`point_to_angle`].
///
/// Original C: `R_PointToAngle2` in `r_main.c` lines 378-387.
///
/// # Arguments
/// * `x1`, `y1` — Source point
/// * `x2`, `y2` — Target point
///
/// # Returns
/// The BAM angle from `(x1, y1)` toward `(x2, y2)`.
pub fn point_to_angle2(x1: Fixed, y1: Fixed, x2: Fixed, y2: Fixed) -> Angle {
    point_to_angle(
        Fixed(x2.0.wrapping_sub(x1.0)),
        Fixed(y2.0.wrapping_sub(y1.0)),
    )
}

